<template><section class="module-page module-composed-page course-platform-page"><header class="course-heading"><div><h1>课程平台</h1><p>按课程浏览电子书、视频、PPT 和课程数据。</p></div><el-button icon="el-icon-monitor" @click="$router.push('/training-environment')">打开实训环境</el-button></header><section class="course-library-toolbar"><el-input v-model="keyword" clearable prefix-icon="el-icon-search" placeholder="输入关键字搜索" /><el-select v-model="type" clearable placeholder="全部课程类型"><el-option v-for="item in types" :key="item" :label="item" :value="item" /></el-select><el-select v-model="status" placeholder="学习状态"><el-option label="全部课程" value="all" /><el-option label="学习中" value="learning" /><el-option label="已完成" value="done" /></el-select><span>共 {{ filtered.length }} 门课程</span></section><div v-if="filtered.length" class="course-library-grid"><article v-for="item in filtered" :key="item.course.courseId" class="library-course-card"><div class="library-cover"><img v-if="coverUrls[item.course.courseId]" :src="coverUrls[item.course.courseId]" :alt="item.course.name"><span v-else><i class="el-icon-reading" /></span><el-tag size="mini" :type="courseDone(item)?'success':'info'">{{ courseDone(item)?'已完成':'学习中' }}</el-tag></div><div class="library-card-body"><h2 :title="item.course.name">{{ item.course.name }}</h2><p>{{ item.course.courseType }} · {{ item.resources.length }} 项资源</p><small>{{ item.course.description || '暂无课程简介' }}</small><div class="library-progress"><el-progress :percentage="courseProgress(item)" :show-text="false" :stroke-width="6" /><span>{{ courseProgress(item) }}%</span></div><footer><el-button size="small" type="primary" @click="$router.push({path:'/training-environment',query:{courseId:item.course.courseId}})">进入实训</el-button><el-button size="small" @click="openFirstResource(item)">开始学习</el-button></footer></div></article></div><div v-else class="course-empty"><i class="el-icon-reading" /><strong>暂无可用课程</strong><span>管理员发布课程后将在此显示。</span></div><el-dialog :title="activeResource ? activeResource.name : '资源预览'" :visible.sync="preview" width="760px"><div v-if="activeResource" class="resource-preview"><el-button v-if="previewUrl" size="small" icon="el-icon-link" @click="windowOpen(previewUrl)">新窗口打开</el-button><iframe v-if="previewUrl && activeResource.resourceType !== 'VIDEO'" :src="previewUrl" class="preview-frame" title="课程资源预览" /><video v-else-if="previewUrl" :src="previewUrl" controls class="preview-video" /><p v-else>正在获取授权预览地址...</p><el-progress :percentage="progress" /><el-button type="primary" @click="finishResource">标记本资源完成</el-button></div></el-dialog></section></template>
<script>
import { listUserCourses, listAdminCourses, listCourseProgress, recordCourseProgress, getCourseResourcePreviewUrl, getCourseCoverUrl } from '@/api/Courses'
import { getRole } from '@/utils/auth'
export default { data:()=>({courses:[],progressRecords:{},coverUrls:{},keyword:'',type:'',status:'all',preview:false,activeResource:null,previewUrl:'',progress:0}),computed:{types(){return [...new Set(this.courses.map(i=>i.course.courseType))]},filtered(){return this.courses.filter(i=>{const done=this.courseDone(i);return(!this.keyword||i.course.name.toLowerCase().includes(this.keyword.toLowerCase()))&&(!this.type||i.course.courseType===this.type)&&(this.status==='all'||(this.status==='done'?done:!done))})}},async created(){const admin=getRole()==='ADMIN';const results=admin?await Promise.all([listAdminCourses()]):await Promise.all([listUserCourses(),listCourseProgress()]);this.courses=results[0].data||[];(results[1]&&results[1].data||[]).forEach(r=>this.$set(this.progressRecords,r.resourceId,Number(r.percent||0)));if(!admin)await this.loadCovers()},methods:{async loadCovers(){const pairs=await Promise.all(this.courses.map(async item=>{try{const result=await getCourseCoverUrl(item.course.courseId);return[item.course.courseId,result.data&&result.data.coverUrl]}catch(e){return[item.course.courseId,'']}}));pairs.forEach(pair=>{if(pair[1])this.$set(this.coverUrls,pair[0],pair[1])})},progressFor(r){return this.progressRecords[r.resourceId]||0},courseProgress(item){if(!item.resources.length)return 0;return Math.round(item.resources.reduce((sum,r)=>sum+this.progressFor(r),0)/item.resources.length)},courseDone(item){return item.resources.length>0&&this.courseProgress(item)>=100},openFirstResource(item){if(item.resources.length)this.openResource(item.resources[0]);else this.$message.info('该课程暂无资源')},openResource(r){this.activeResource=r;this.progress=this.progressFor(r);this.previewUrl='';this.preview=true;getCourseResourcePreviewUrl(r.resourceId).then(result=>{this.previewUrl=result.data&&result.data.previewUrl}).catch(()=>this.$message.error('资源预览地址获取失败'))},windowOpen(url){window.open(url,'_blank','noopener,noreferrer')},async finishResource(){if(getRole()==='ADMIN')return;await recordCourseProgress({resourceId:this.activeResource.resourceId,progressKind:this.activeResource.resourceType==='VIDEO'?'TIME':(this.activeResource.resourceType==='PPT'?'SLIDE':'PAGE'),progressValue:100,completed:true});this.progressRecords[this.activeResource.resourceId]=100;this.progress=100;this.$message.success('学习进度已记录')}}}
</script>
<style scoped>.course-platform-page{width:100%}.course-heading{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:18px}.course-heading h1{margin:0;font-size:28px}.course-heading p{margin:6px 0 0;color:var(--ui-muted);font-size:13px}.course-library-toolbar{display:flex;align-items:center;gap:12px;margin-bottom:18px;padding:14px 16px;background:var(--ui-surface);border-radius:12px;box-shadow:var(--ui-shadow)}.course-library-toolbar .el-input{width:min(360px,100%)}.course-library-toolbar .el-select{width:170px}.course-library-toolbar>span{margin-left:auto;color:var(--ui-muted);font-size:12px}.course-library-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.library-course-card{overflow:hidden;background:#fff;border:1px solid var(--ui-border);border-radius:12px;box-shadow:var(--ui-shadow)}.library-cover{position:relative;height:142px;overflow:hidden;background:linear-gradient(135deg,#dfe5ff,#dff7f1)}.library-cover img{width:100%;height:100%;object-fit:cover}.library-cover>span{display:grid;place-items:center;height:100%;color:var(--ui-primary);font-size:44px}.library-cover .el-tag{position:absolute;top:12px;right:12px}.library-card-body{padding:16px}.library-card-body h2{margin:0;overflow:hidden;font-size:17px;text-overflow:ellipsis;white-space:nowrap}.library-card-body p{margin:7px 0;color:var(--ui-primary-strong);font-size:12px}.library-card-body>small{display:block;min-height:38px;overflow:hidden;color:var(--ui-muted);font-size:12px;line-height:1.6}.library-progress{display:flex;align-items:center;gap:10px;margin-top:14px}.library-progress .el-progress{flex:1}.library-progress span{color:var(--ui-muted);font-size:12px}.library-card-body footer{display:flex;gap:8px;margin-top:14px}.library-card-body footer .el-button{flex:1}.course-empty{display:grid;place-items:center;gap:8px;min-height:300px;color:var(--ui-muted);background:#fff;border:1px solid var(--ui-border);border-radius:12px}.course-empty i{font-size:44px;color:var(--ui-primary)}.course-empty strong{color:var(--ui-text);font-size:18px}.course-empty span{font-size:13px}.preview-frame{display:block;width:100%;height:430px;border:1px solid var(--ui-border);margin:12px 0}.preview-video{display:block;width:100%;max-height:430px;margin:12px 0}@media(max-width:950px){.course-library-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.course-heading{display:block}.course-heading .el-button{margin-top:12px}.course-library-toolbar{align-items:stretch;flex-direction:column}.course-library-toolbar .el-input,.course-library-toolbar .el-select{width:100%}.course-library-toolbar>span{margin-left:0}.course-library-grid{grid-template-columns:1fr}}
</style>
